import numpy as np
import pandas as pd

def model(regime, n, seed):
    rng = np.random.default_rng(seed)

    if "T" in regime.config:
        T = float(regime.config["T"])
    else:
        T = 1.0

    mu = 91.83493828962008 + (-1.6900810067305096) * (T - 1.0) + (-9.39307091163264) * max(T - 1.2, 0.0)

    p_bad = 0.06875 + 0.40625 * (T - 1.0)
    if T < 1.0:
        p_bad = 0.06875 + 0.09375 * (T - 1.0)
    if p_bad < 0.02:
        p_bad = 0.02
    if p_bad > 0.35:
        p_bad = 0.35

    is_bad = rng.random(n) < p_bad
    y = np.empty(n, dtype=float)

    ng = int((~is_bad).sum())
    nb = int(is_bad.sum())

    if ng > 0:
        y[~is_bad] = mu + rng.normal(0.40403905348137314, 1.2677685977204973, size=ng)
    if nb > 0:
        y[is_bad] = mu + rng.normal(-3.48670738745067, 1.2008099435439392, size=nb)

    return pd.DataFrame({"unit_id": np.arange(n, dtype=int), "y": y})
